-- zh-CN 공식 계정(pinwith_zhcn)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('zh-CN', 'zhcn', $doc${"official":{"display_name":"PinWith 官方","bio":"PinWith 团队精选的地点清单。"},"samples":[{"display_name":"示例用户1","bio":"这是 PinWith 创建的示例账号，用来展示朋友们如何一起规划旅行。"},{"display_name":"示例用户2","bio":"这是 PinWith 创建的示例账号，用来展示朋友们如何一起规划旅行。"},{"display_name":"示例用户3","bio":"这是 PinWith 创建的示例账号，用来展示朋友们如何一起规划旅行。"}],"lists":[{"role":"plain","owner":"official","slug":"shanghai-citywalk-classic","kind":"course","title":"上海经典 Citywalk：从豫园走到外滩","desc":"第一次来上海也不会踩雷的一条步行路线：老城厢的烟火气、石库门弄堂和外滩万国建筑，一天慢慢走完。","themes":["citywalk","上海","老城厢","石库门","外滩"],"sections":[{"name":"上午：老城厢","by":"official","items":[{"place_id":"ChIJidPZMUGHrTUR29eIuHbpoIQ","title":"豫园","memo":"明代江南园林，建议开门后尽早进园，人少时更能看清假山和回廊的细节。","tags":["园林","早去人少"],"lat":31.227236,"lng":121.492094},{"place_id":"ChIJP5OCAWBwsjURfYtYWcmjxXU","title":"豫园老街","memo":"九曲桥、湖心亭一带适合拍照，小吃店多但排队长，挑一两家尝尝就好。","tags":["小吃","拍照"],"lat":31.227392,"lng":121.491391},{"place_id":"ChIJV5LAV4twsjURVTbWYnxGe8M","title":"上海老街","memo":"方浜中路上的老字号和小店，比豫园商城里面稍微清静一些，适合顺路逛逛。","tags":["老字号","顺路"],"lat":31.225319,"lng":121.496944}]},{"name":"下午：石库门弄堂","by":"official","items":[{"place_id":"ChIJ2-UI76F6sjURj_HAeG5PMhE","title":"田子坊","memo":"泰康路的弄堂里藏着小店和咖啡馆，往里面多拐几个弯，比主路有意思得多。","tags":["弄堂","文创"],"lat":31.208812,"lng":121.468898},{"place_id":"ChIJ58wtg3FwsjURJN5JhiyQYOI","title":"新天地","memo":"石库门建筑改造的街区，走累了可以在这里找家店坐下歇脚，晚上氛围更好。","tags":["石库门","歇脚"],"lat":31.21916,"lng":121.474878}]},{"name":"傍晚：外滩","by":"official","items":[{"place_id":"ChIJYUiHi1dwsjURZK_REO37Vk0","title":"外滩","memo":"日落前后到最好，先看万国建筑群，等陆家嘴亮灯再拍对岸夜景；节假日晚上人非常多。","tags":["夜景","万国建筑","日落"],"lat":31.240261,"lng":121.490577}]}],"comments":[]},{"role":"creator","owner":"official","slug":"chongqing-8d-city-vlog-2days","kind":"course","title":"【Vlog】两天打卡8D魔幻重庆","desc":"跟着镜头穿楼过江！两天把洪崖洞、李子坝、长江索道这些名场面一次拍够，附机位和最佳拍摄时间。","themes":["重庆","8D魔幻城市","Vlog","夜景","机位"],"sections":[{"name":"Day1 渝中半岛","by":"official","items":[{"place_id":"ChIJSTbOLUvL7DYRj2MTRmh6w2o","title":"李子坝轻轨穿楼","memo":"视频里3:20那段“列车穿楼”就是在对面观景台拍的，提前查好班次间隔，开连拍等列车钻进楼里。","tags":["名场面","连拍"],"lat":29.551185,"lng":106.534521},{"place_id":"ChIJu9XkaLU0kzYRjkeA8L0mSzU","title":"鹅岭公园","memo":"比主城网红点清静，瞰胜楼一带能俯拍两江和城市层叠感，下午光线柔和。","tags":["俯拍","清静"],"lat":29.54974,"lng":106.53616},{"place_id":"ChIJlcGJoIA0kzYRo8arbwJo1r0","title":"罗汉寺","memo":"闹市里的千年古寺，进去就安静下来了，拍空镜很出片，记得尊重寺内拍摄规定。","tags":["古寺","空镜"],"lat":29.559891,"lng":106.581916},{"place_id":"ChIJw2Yqr4E0kzYRwPSNgwikEQY","title":"洪崖洞","memo":"天黑亮灯后才是本体！对岸千厮门大桥上或江边拍全景，人多时手机注意防挤。","tags":["夜景","必拍"],"lat":29.562273,"lng":106.579177}]},{"name":"Day2 跨江南岸","by":"official","items":[{"place_id":"ChIJETuQ7300kzYR95vE7yxNBzE","title":"长江索道","memo":"我在视频里是靠窗站着拍的，车厢一动就开录，过江那一分钟两岸高楼一起往后退，超有电影感。排队可能很久，建议错峰。","tags":["过江","错峰"],"lat":29.557701,"lng":106.582752},{"place_id":"ChIJn_5xt3A0kzYRM4fCyK9PFD8","title":"龙门浩老街","memo":"南岸的老街，回头就能拍到渝中半岛天际线，蓝调时刻最美。","tags":["天际线","蓝调时刻"],"lat":29.55635,"lng":106.59501},{"place_id":"ChIJRX95y2k0kzYRGkr8Egt3Iks","title":"黄葛古道","memo":"石阶古道一路往上爬，穿运动鞋，绿荫里拍走路的跟拍镜头很有氛围。","tags":["古道","跟拍"],"lat":29.54092,"lng":106.596938},{"place_id":"ChIJve0_K4EzkzYRAQqD2GL_K0I","title":"朝天门广场","memo":"两江交汇处，晚上可以拍来福士和江上游船的灯光，作为Vlog结尾刚刚好。","tags":["两江交汇","结尾镜头"],"lat":29.566623,"lng":106.587785}]},{"name":"有空再去","by":"official","items":[{"place_id":"ChIJ8xTyJvjL7DYRaxlsvpdbeTE","title":"磁器口古镇","memo":"离市中心稍远，早上去人少好拍；周末下午基本是人挤人。","tags":["古镇","早去"],"lat":29.579389,"lng":106.45168}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"seoul-jeju-4days-friends","kind":"collection","title":"三人行：首尔+济州4天3晚","desc":"三个好朋友各自挑了想去的地方，在评论里边聊边定路线。最终行程写在“东门市场”的评论里！","themes":["首尔","济州岛","闺蜜旅行","韩国自由行"],"sections":[{"name":"小A想去：首尔老城","by":"ex1","items":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","title":"景福宫","memo":"穿韩服进宫可以免门票，宫门前有守门将换岗仪式，记得提前看时间。","tags":["韩服","宫殿"],"lat":37.579617,"lng":126.977041},{"place_id":"ChIJT8H4r9qifDURmuXJ_6m6vM0","title":"北村韩屋村","memo":"居民区，有限制游览时段，说话小声一点；坡多穿平底鞋。","tags":["韩屋","拍照"],"lat":37.58147,"lng":126.984952},{"place_id":"ChIJe4Jbot2ifDUR2zWhruwyaow","title":"益善洞","memo":"韩屋改造的咖啡馆和小店，巷子窄，周末下午人很多。","tags":["咖啡","韩屋"],"lat":37.573713,"lng":126.990127},{"place_id":"ChIJm3V0fu2ifDURRJ8IMUijVtY","title":"广藏市场","memo":"绿豆煎饼和生拌牛肉是招牌，现金和刷卡都备着。","tags":["市场","小吃"],"lat":37.570039,"lng":126.999604}]},{"name":"小B想去：逛街+夜景","by":"ex2","items":[{"place_id":"ChIJqb-ne_CifDURR-yH8a3sjXM","title":"明洞","memo":"化妆品店扎堆，傍晚后街边小吃摊陆续出来，退税记得带护照。","tags":["购物","退税"],"lat":37.561669,"lng":126.985844},{"place_id":"ChIJ68AiKsWYfDUROpTctLKtxtU","title":"弘大","memo":"年轻人聚集地，晚上有街头表演，周边服饰小店价格友好。","tags":["街头表演","夜生活"],"lat":37.556197,"lng":126.925034},{"place_id":"ChIJHb1ypJWkfDURb2d4XCjLluM","title":"圣水洞 Onion","memo":"旧工厂改造的面包咖啡店，人气高，避开周末中午。","tags":["面包","工业风"],"lat":37.544733,"lng":127.058209},{"place_id":"ChIJqWqOqFeifDURpYJ5LnxX-Fw","title":"N首尔塔","memo":"坐缆车或步行上南山，晚上看首尔夜景，风大带件外套。","tags":["夜景","南山"],"lat":37.551169,"lng":126.988227}]},{"name":"小C想去：济州岛","by":"ex3","items":[{"place_id":"ChIJn3jj9rkUDTURS7YjOgUyUVU","title":"城山日出峰","memo":"登顶看日出要早起，往返大概一小时左右，台阶多。","tags":["日出","徒步"],"lat":33.458056,"lng":126.9425},{"place_id":"ChIJA_du00wVDTURisfAXXmN2fQ","title":"牛岛","memo":"从城山港坐船过去，岛上租电动车环岛，花生冰淇淋必吃；风浪大时可能停航。","tags":["海岛","骑行"],"lat":33.504298,"lng":126.954048},{"place_id":"ChIJVSv3qq_8DDURcLh4pWxZ0vA","title":"咸德海边","memo":"海水颜色很漂亮，离济州市区近，适合到达当天去。","tags":["海边","近市区"],"lat":33.543423,"lng":126.669775},{"place_id":"ChIJEczrGRJdDDUR0cpD2okSp7g","title":"OSULLOC 茶博物馆","memo":"绿茶田和抹茶甜品，在西南边，和东边景点不顺路。","tags":["抹茶","茶园"],"lat":33.305939,"lng":126.289435},{"place_id":"ChIJpyFxA1TjDDUR1kddP-9mN0Y","title":"东门市场","memo":"济州市区的传统市场，晚上有夜市，适合买柑橘和吃海鲜。","tags":["夜市","柑橘"],"lat":33.512212,"lng":126.528202}]}],"comments":[{"place_id":"ChIJod7tSseifDUR9hXHLFNGMIs","by":"ex1","body":"第一天落地首尔，下午直接去景福宫+北村吧？穿韩服进宫还能免票，拍照也好看。","replies":[{"by":"ex2","body":"可以！但韩服租借店要提前约，下午那个点人太多了。"},{"by":"ex3","body":"那北村别逛太晚，好像傍晚以后就不让游客进了，我们先北村再景福宫。"}]},{"place_id":"ChIJHb1ypJWkfDURb2d4XCjLluM","by":"ex2","body":"圣水洞想去！面包店+买手店一下午都逛不完。","replies":[{"by":"ex1","body":"它和弘大是反方向的，一天只能二选一，你挑一个？"},{"by":"ex2","body":"那选圣水，弘大晚上去看街头表演就行，白天不用专门去。"}]},{"place_id":"ChIJA_du00wVDTURisfAXXmN2fQ","by":"ex3","body":"济州我们只有两天，牛岛要占大半天，你们觉得值吗？","replies":[{"by":"ex1","body":"值！但要看天气，风大会停船。先看预报，不行就换咸德海边。"}]},{"place_id":"ChIJEczrGRJdDDUR0cpD2okSp7g","by":"ex1","body":"OSULLOC在西南边，跟城山日出峰一东一西，开车单程得一个多小时。","replies":[{"by":"ex3","body":"那就砍掉吧😭 抹茶甜品在机场或市区也能买到。"},{"by":"ex2","body":"同意，预算也省点，租车油钱少一点。"}]},{"place_id":"ChIJpyFxA1TjDDUR1kddP-9mN0Y","by":"ex1","body":"最终行程定了！Day1 首尔：北村→景福宫→广藏市场晚饭。Day2：圣水洞→明洞购物→晚上N首尔塔看夜景（弘大有空再去）。Day3 飞济州：咸德海边→晚上东门市场夜市。Day4：早起城山日出峰→牛岛（停航就改沿海公路兜风）→傍晚还车去机场。","replies":[{"by":"ex2","body":"完美！明洞那天我负责查退税，大家都带好护照。"},{"by":"ex3","body":"租车我来订，城山那天五点多要起床，谁都不许赖床！"}]}]},{"role":"food","owner":"official","slug":"chengdu-hotpot-food-list","kind":"collection","title":"成都火锅与本地味道","desc":"来成都不吃火锅等于白来。从老派牛油锅到市井苍蝇馆子，按自己的嗜辣程度挑一家。","themes":["成都","火锅","川味","美食"],"sections":[{"name":"老成都火锅","by":"official","items":[{"place_id":"ChIJ_7OiCzHF7zYRcuKZ00fHszA","title":"蜀大侠（骡马市店）","memo":"市中心热门店，饭点基本要排号，可以先线上取号再去附近逛逛。","tags":["人气","先取号"],"lat":30.66724,"lng":104.06846},{"place_id":"ChIJP1D300HF7zYRmglfpJEg6Ns","title":"小龙坎老火锅","memo":"连锁老牌，锅底偏麻辣厚重，不太能吃辣的可以点鸳鸯锅。","tags":["鸳鸯锅","老牌"],"lat":30.651056,"lng":104.080121},{"place_id":"ChIJlaUzUznF7zYRr5V-MA-HIMk","title":"朝天门火锅","memo":"牛油锅底香味很足，毛肚、鸭肠记得“七上八下”涮几秒就捞。","tags":["牛油锅","毛肚"],"lat":30.65727,"lng":104.07158},{"place_id":"ChIJySWBUrXa7zYRQUwPvdikSZM","title":"巴蜀大宅门火锅","memo":"店面有川西老宅氛围，适合带外地朋友来吃一顿有仪式感的火锅。","tags":["环境","请客"],"lat":30.673657,"lng":104.077609}]},{"name":"本地人常去","by":"official","items":[{"place_id":"ChIJlW_89DjF7zYRE8GzbZ6JV0E","title":"西林门火锅（提督街店）","memo":"离春熙路不远，口味地道，蘸油碟时加点蒜泥和香菜更解辣。","tags":["油碟","地道"],"lat":30.65947,"lng":104.0753},{"place_id":"ChIJbVu396vF7zYR0Li6WnE-0lk","title":"蜀九香火锅（武侯）","memo":"菜品新鲜、服务稳定，人多聚餐不容易踩雷，晚上建议提前订位。","tags":["聚餐","订位"],"lat":30.625009,"lng":104.058456}]},{"name":"火锅之外","by":"official","items":[{"place_id":"ChIJHzxzuC3b7zYR3O6yGLZ8tAw","title":"陶德砂锅（营门口店）","memo":"成都人很爱的砂锅，一个人也能吃，想换换口味不吃火锅时来这里。","tags":["砂锅","一人食"],"lat":30.681367,"lng":104.044146},{"place_id":"ChIJjxnbZtzE7zYRa1rID6mDC2M","title":"龙森园","memo":"琴台路附近的川菜馆，吃完可以顺路去散步消食。","tags":["川菜","琴台路"],"lat":30.658878,"lng":104.045348}]}],"comments":[]}]}$doc$::jsonb);
